from decimal import Decimal

from rest_framework import serializers

from common.models import phone_validator


class PosSaleLineSerializer(serializers.Serializer):
    variant_id = serializers.UUIDField()
    quantity = serializers.IntegerField(min_value=1, max_value=999)


class PosSaleCreateSerializer(serializers.Serializer):
    """Body of the counter "Confirm Sale" action."""

    # Idempotency key generated by the POS client (survives a retry/double tap).
    client_reference = serializers.CharField(
        max_length=64, required=False, allow_blank=True, allow_null=True
    )
    pos_terminal = serializers.CharField(
        max_length=64, required=False, allow_blank=True, default=""
    )
    # Sell units that online customers have reserved. Requires an explicit
    # cashier decision, never a default.
    allow_reserved_override = serializers.BooleanField(required=False, default=False)
    items = PosSaleLineSerializer(many=True, allow_empty=False)

    def validate_items(self, items):
        if len(items) > 200:
            raise serializers.ValidationError("Too many lines for one sale.")
        return items


class PosInvoiceUpdateSerializer(serializers.Serializer):
    """Optional post-sale invoice fields (the dismissible modal)."""

    customer_phone = serializers.CharField(
        max_length=15,
        required=False,
        allow_blank=True,
        validators=[phone_validator],
    )
    discount_type = serializers.ChoiceField(
        choices=["percent", "flat"], required=False
    )
    discount_value = serializers.DecimalField(
        max_digits=10, decimal_places=2, min_value=Decimal("0"), required=False
    )
    notes = serializers.CharField(
        max_length=2000, required=False, allow_blank=True
    )

    def validate(self, attrs):
        has_type = "discount_type" in attrs
        has_value = "discount_value" in attrs
        if has_type != has_value:
            raise serializers.ValidationError(
                {
                    "detail": "discount_type and discount_value must be sent together.",
                    "code": "discount_incomplete",
                }
            )
        return attrs
